// Chat.jsx
import React, { useEffect, useState, useRef } from 'react';
import * as openpgp from 'openpgp';
import { v4 as uuidv4 } from 'uuid';
import {
  generateKeys,
  encryptMessage,
  decryptMessage,
  storePrivateKey,
  retrievePrivateKey,
} from '../utils/crypto';
import {
  encryptPrivateKey,
  decryptPrivateKey,
} from '../utils/cryptoProtection';
import { sha256 } from 'js-sha256'; // Пока не используется – можно удалить, если не нужно

// Компонент чата
const Chat = () => {
  // Состояния для сообщений, поля ввода и ключей
  const [messages, setMessages] = useState([]); // история сообщений
  const [input, setInput] = useState(''); // текст сообщения
  const [keys, setKeys] = useState({
    publicKey: null,
    recipientPublicKey: null,
  }); // ключи пользователя и собеседника

  // useRef для хранения приватного ключа и WebSocket-соединения (чтобы не вызывать перерендер)
  const privateKeyRef = useRef(null);
  const wsRef = useRef(null);

  useEffect(() => {
    const initChat = async () => {
      try {
        // 1. Получение или генерация уникального clientId
        let clientId = localStorage.getItem('clientId');
        if (!clientId) {
          clientId = uuidv4();
          localStorage.setItem('clientId', clientId);
          console.log('Создан новый clientId:', clientId);
        } else {
          console.log('Используется существующий clientId:', clientId);
        }

        // 2. Получение приватного ключа из IndexedDB
        let storedKey = await retrievePrivateKey();
        let privateKey;
        let publicKey;
        // Предполагаем, что для защиты ключа используется шифрование,
        // и зашифрованный ключ будет содержать разделители (например, двоеточия)
        const passphrase = prompt('Введите секретную фразу для защиты ваших ключей');

        if (!storedKey) {
          // Если ключ не найден – генерируем новый
          const generatedKeys = await generateKeys();
          privateKey = generatedKeys.privateKey;
          publicKey = generatedKeys.publicKey;
          // Шифруем приватный ключ перед сохранением
          const protectedKey = await encryptPrivateKey(privateKey, passphrase);
          await storePrivateKey(protectedKey);
          console.log('Ключи сгенерированы, защищены и сохранены');
        } else {
          // Если ключ найден, проверяем его формат:
          // если строка содержит разделитель ":", считаем, что ключ зашифрован,
          // иначе – не защищён (в целях совместимости)
          if (storedKey.includes(':')) {
            privateKey = await decryptPrivateKey(storedKey, passphrase);
            console.log('Приватный ключ дешифрован из хранилища');
          } else {
            privateKey = storedKey;
            console.log('Приватный ключ загружен из хранилища (без защиты)');
          }
          // Получаем публичный ключ из приватного
          const extractedKey = await openpgp.readKey({ armoredKey: privateKey });
          publicKey = extractedKey.toPublic().armor();
        }

        // Сохраняем приватный ключ в useRef и обновляем состояние с публичным ключом
        privateKeyRef.current = privateKey;
        setKeys((prevKeys) => ({ ...prevKeys, publicKey }));

        // 3. Подключение к WebSocket-серверу (создаём соединение, если его ещё нет)
        if (!wsRef.current) {
          console.log('Инициализация WebSocket-соединения...');
          wsRef.current = new WebSocket('ws://localhost:8080');
        }
        wsRef.current.onopen = () => {
          console.log('WebSocket подключен');
          if (clientId && publicKey) {
            // Отправляем сообщение обмена ключами на сервер
            wsRef.current.send(
              JSON.stringify({
                type: 'key_exchange',
                publicKey,
                clientId,
              })
            );
            console.log('Публичный ключ и clientId отправлены на сервер');
          } else {
            console.error('Отсутствует clientId или publicKey');
          }
        };

        // 4. Обработка входящих сообщений
        wsRef.current.onmessage = async (event) => {
          const data = JSON.parse(event.data);
          console.log('Получено сообщение от сервера:', data);

          if (data.type === 'key_exchange' && data.publicKey) {
            // Сохраняем публичный ключ собеседника
            setKeys((prevKeys) => ({
              ...prevKeys,
              recipientPublicKey: data.publicKey,
            }));
            console.log('Получен публичный ключ другого клиента:', data.publicKey);
          } else if (data.type === 'message') {
            try {
              // Расшифровываем сообщение с использованием приватного ключа
              const decryptedMessage = await decryptMessage(
                data.encryptedMessage,
                privateKeyRef.current
              );
              // Добавляем сообщение в историю
              setMessages((prev) => [
                ...prev,
                { userId: data.clientId, text: decryptedMessage },
              ]);
            } catch (err) {
              console.error('Ошибка расшифровки сообщения:', err);
            }
          }
        };

        // 5. Обработка ошибок и закрытия соединения
        wsRef.current.onerror = (err) => {
          console.error('WebSocket error:', err);
        };

        wsRef.current.onclose = (event) => {
          console.log('WebSocket connection closed', event);
          wsRef.current = null;
        };
      } catch (err) {
        console.error('Ошибка инициализации чата:', err);
      }
    };

    initChat();

    // Очистка при размонтировании компонента
    return () => {
      if (wsRef.current) {
        console.log('Закрытие WebSocket-соединения при размонтировании.');
        wsRef.current.close();
      }
    };
  }, []); // Запускаем эффект только один раз при монтировании

  // Функция отправки текстового сообщения
  const sendMessage = async (message) => {
    if (!wsRef.current || wsRef.current.readyState !== WebSocket.OPEN) {
      console.error('WebSocket не подключен');
      return;
    }

    if (!keys.recipientPublicKey) {
      console.error('Публичный ключ получателя отсутствует');
      return;
    }

    try {
      // Шифруем сообщение с использованием публичного ключа собеседника
      const encryptedMessage = await encryptMessage(
        message,
        keys.recipientPublicKey
      );
      // Отправляем зашифрованное сообщение на сервер
      wsRef.current.send(
        JSON.stringify({
          type: 'message',
          encryptedMessage,
          clientId: localStorage.getItem('clientId'),
        })
      );
      // Добавляем отправленное сообщение в локальную историю (отправитель видит его сразу)
      // setMessages((prev) => [...prev, { userId: 'Вы', text: message }]);
      setInput(''); // Очищаем поле ввода
    } catch (err) {
      console.error('Ошибка отправки сообщения:', err);
    }
  };

  return (
    <div>
      <h1>Anonymous Chat</h1>
      {!keys.recipientPublicKey && (
        <p style={{ color: 'red' }}>
          Ожидание публичного ключа другого клиента. Подключите второго клиента для начала общения.
        </p>
      )}
      <div>
        {messages.map((msg, index) => (
          <p key={index}>
            <strong>{msg.userId}:</strong> {msg.text}
          </p>
        ))}
      </div>
      <input
        type="text"
        value={input}
        onChange={(e) => setInput(e.target.value)}
        placeholder="Введите сообщение..."
      />
      <button onClick={() => sendMessage(input)} disabled={!keys.recipientPublicKey}>
        Отправить
      </button>
    </div>
  );
};

export default Chat;
